import base64, re
text = base64.b64decode("{{clipboard.text.b64}}").decode("utf-8", "replace").strip()
findings = []
patterns = [
    ("BTC private key WIF", r"\b[5KL][1-9A-HJ-NP-Za-km-z]{50,51}\b"),
    ("64-char hex secret/hash", r"\b[0-9a-fA-F]{64}\b"),
    ("credit-card-like number", r"\b\d{4}[- ]?\d{4}[- ]?\d{4}[- ]?\d{4}\b"),
    ("onion address", r"\b[a-z2-7]{56}\.onion\b"),
    ("private key block", r"-----BEGIN [A-Z ]*PRIVATE KEY-----"),
]
words = re.findall(r"[a-z]+", text.lower())
if len(words) in (12, 24): findings.append("possible seed phrase word count")
for label, pattern in patterns:
    if re.search(pattern, text): findings.append(label)
print("CLIPBOARD SECURITY SCAN")
if findings:
    print("Status: ALERT")
    for f in findings: print("- " + f)
    print("Recommendation: wipe clipboard after use or save only in encrypted vault.")
else:
    print("Status: CLEAN")
    print("No common sensitive pattern detected.")
